body.script:
(function () {
  var _u = document.getElementById('nexi-build-urls') || {};
  var FINALIZE_URL = (_u.dataset || {}).finalize || '';
  var CONFIRM_URL = (_u.dataset || {}).confirm || '';
  function fail(msg) {
    var e = document.getElementById('nexi-build-error');
    e.textContent = msg; e.classList.remove('d-none');
  }
  // Nessuna navigazione verso URL che non siano Nexi: il valore può
  // arrivare dall'SDK o da una risposta alterata.
  function nexiUrlOk(u) {
    try {
      var x = new URL(u, window.location.href);
      if (x.protocol !== 'https:') { return false; }
      var h = x.hostname.toLowerCase();
      return h === 'xpay.nexigroup.com' || h === 'xpaysandbox.nexigroup.com';
    } catch (e) { return false; }
  }
  function iframeFor(f, height) {
    var i = document.createElement('iframe');
    i.src = f.src; i.scrolling = 'no';
    // Titolo e nome: aiutano lettori di schermo e compilatori
    // automatici a capire cos'e' il campo dentro l'iframe.
    var _titles = {CARD_NUMBER: 'Numero carta', EXPIRATION_DATE: 'Scadenza', SECURITY_CODE: 'Codice di sicurezza', CARDHOLDER_NAME: 'Nome e cognome', CARDHOLDER_SURNAME: 'Cognome', CARDHOLDER_EMAIL: 'Email'};
    i.setAttribute('title', 'Nexi - ' + (_titles[f.id] || f.id || 'campo carta'));
    i.setAttribute('name', 'nexi-' + String(f.id || 'campo').toLowerCase().replace(/_/g, '-'));
    i.style.border = '0'; i.style.width = '100%';
    i.style.height = height || '60px';
    return i;
  }
  var build = null;
  try {
    build = new Build({
      onBuildFlowStateChange: function (evtData, workflowState) {
        var d = evtData || {};
        var state = d.state || workflowState || '';
        if (d.url) { if (!nexiUrlOk(d.url)) { fail('Risposta Nexi non valida.'); return; } window.location.href = d.url; return; }
        if (d.fieldSet && d.fieldSet.fields) {
          var box = document.getElementById('nexi-build-fields');
          box.innerHTML = '';
          d.fieldSet.fields.forEach(function (f) {
            if (!f.src) return;
            box.appendChild(iframeFor(f, '60px'));
          });
          document.getElementById('nexi-build-privacy-wrap').classList.remove('d-none');
          document.getElementById('nexi-build-pay').classList.remove('d-none');
        }
        if (state === 'READY_FOR_PAYMENT') { finalize(); }
        if (state === 'PAYMENT_COMPLETE') { window.location.href = CONFIRM_URL; }
      },
      onBuildError: function (d) { fail('Errore Nexi. Riprova.'); },
      onConfirmError: function (d) { fail('Dati non validi. Controlla e riprova.'); },
    });
  } catch (e) { fail('SDK Nexi non caricato. Riprova.'); }
  function finalize() {
    fetch(FINALIZE_URL, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: '{}',
    }).then(function (r) { return r.json(); }
    ).then(function (res) {
      var r = (res && res.result) || res || {};
      if (r.error) { fail('Nexi: ' + r.error); return; }
      if (r.url) { if (!nexiUrlOk(r.url)) { fail('Risposta Nexi non valida.'); return; } window.location.href = r.url; return; }
      window.location.href = CONFIRM_URL;
    }).catch(function () { fail('Conferma non riuscita. Riprova.'); });
  }
  document.getElementById('nexi-build-pay').addEventListener('click', function () {
    if (!document.getElementById('nexi-build-privacy').checked) {
      fail('Spunta la privacy per continuare.'); return;
    }
    if (build) { build.confirmData(function () {}); }
  });
})();

t.script:
(function () {
  var _b = document.getElementById('nexi-build-box') || {};
  var _d = _b.dataset || {};
  var FIELDS_URL = _d.fields || '';
  var FINALIZE_URL = _d.finalize || '';
  var CONFIRM_URL = _d.confirm || '';
  function fail(msg) {
    var e = document.getElementById('nexi-build-error');
    e.textContent = msg; e.classList.remove('d-none');
  }
  // Nessuna navigazione verso URL che non siano Nexi: il valore può
  // arrivare dall'SDK o da una risposta alterata.
  function nexiUrlOk(u) {
    try {
      var x = new URL(u, window.location.href);
      if (x.protocol !== 'https:') { return false; }
      var h = x.hostname.toLowerCase();
      return h === 'xpay.nexigroup.com' || h === 'xpaysandbox.nexigroup.com';
    } catch (e) { return false; }
  }
  function iframeFor(f, height) {
    var i = document.createElement('iframe');
    i.src = f.src; i.scrolling = 'no';
    // Titolo e nome: aiutano lettori di schermo e compilatori
    // automatici a capire cos'e' il campo dentro l'iframe.
    var _titles = {CARD_NUMBER: 'Numero carta', EXPIRATION_DATE: 'Scadenza', SECURITY_CODE: 'Codice di sicurezza', CARDHOLDER_NAME: 'Nome e cognome', CARDHOLDER_SURNAME: 'Cognome', CARDHOLDER_EMAIL: 'Email'};
    i.setAttribute('title', 'Nexi - ' + (_titles[f.id] || f.id || 'campo carta'));
    i.setAttribute('name', 'nexi-' + String(f.id || 'campo').toLowerCase().replace(/_/g, '-'));
    i.style.border = '0'; i.style.width = '100%';
    i.style.height = height || '60px';
    i.setAttribute('data-build-id', f.id || '');
    return i;
  }
  function showMethods(fields) {
    var box = document.getElementById('nexi-build-methods');
    box.innerHTML = '';
    (fields || []).forEach(function (f) {
      if (!f.src) return;
      var wrap = document.createElement('div');
      wrap.appendChild(iframeFor(f, f.class === 'APM' ? '60px' : '70px'));
      box.appendChild(wrap);
    });
    if (!box.children.length) fail('Nessun metodo disponibile su questo terminale.');
  }
  fetch(FIELDS_URL, {headers: {'Accept': 'application/json'}}).then(function (r) {
    return r.json();
  }).then(function (data) {
    var fs = data.fieldSet || data;
    showMethods(fs.fields);
  }).catch(function () { fail('Metodi non caricati. Riprova.'); });
  var build = null;
  try {
    build = new Build({
      onBuildFlowStateChange: function (evtData, workflowState) {
        var d = evtData || {};
        var state = d.state || workflowState || '';
        if (d.url) { if (!nexiUrlOk(d.url)) { fail('Risposta Nexi non valida.'); return; } window.location.href = d.url; return; }
        if (d.fieldSet && d.fieldSet.fields) {
          var box = document.getElementById('nexi-build-fields');
          box.innerHTML = '';
          d.fieldSet.fields.forEach(function (f) {
            if (!f.src) return;
            box.appendChild(iframeFor(f, '60px'));
          });
          document.getElementById('nexi-build-privacy-wrap').classList.remove('d-none');
          document.getElementById('nexi-build-pay').classList.remove('d-none');
        }
        if (state === 'READY_FOR_PAYMENT') { finalize(); }
        if (state === 'PAYMENT_COMPLETE') { window.location.href = CONFIRM_URL; }
      },
      onBuildError: function (d) { fail('Errore Nexi. Riprova.'); },
      onConfirmError: function (d) { fail('Dati non validi. Controlla e riprova.'); },
    });
  } catch (e) { fail('SDK Nexi non caricato. Riprova.'); }
  function finalize() {
    fetch(FINALIZE_URL, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: '{}',
    }).then(function (r) { return r.json(); }
    ).then(function (res) {
      var r = (res && res.result) || res || {};
      if (r.error) { fail('Nexi: ' + r.error); return; }
      if (r.url) { if (!nexiUrlOk(r.url)) { fail('Risposta Nexi non valida.'); return; } window.location.href = r.url; return; }
      window.location.href = CONFIRM_URL;
    }).catch(function () { fail('Conferma non riuscita. Riprova.'); });
  }
  document.getElementById('nexi-build-pay').addEventListener('click', function () {
    if (!document.getElementById('nexi-build-privacy').checked) {
      fail('Spunta la privacy per continuare.'); return;
    }
    if (build) { build.confirmData(function () {}); }
  });
})();

xpath.script:
(function () {
  var form = document.getElementById('o_payment_form');
  if (!form || form.dataset.nexiBnpl) { return; }
  form.dataset.nexiBnpl = '1';
  function show(msg) {
    var t = document.getElementById('nexi-bnpl-toast');
    if (!t) {
      t = document.createElement('div');
      t.id = 'nexi-bnpl-toast';
      t.style.cssText = 'position:fixed;left:50%;bottom:24px;transform:translateX(-50%);' +
        'background:#8b1b1b;color:#fff;padding:10px 16px;border-radius:8px;z-index:9999;' +
        'font-size:14px;box-shadow:0 4px 14px rgba(0,0,0,.25)';
      document.body.appendChild(t);
    }
    t.textContent = msg;
    t.style.display = 'block';
    clearTimeout(t._h);
    t._h = setTimeout(function () { t.style.display = 'none'; }, 6000);
  }
  function tooSmall() {
    var sel = form.querySelector('input[name="o_payment_radio"]:checked');
    var code = sel ? (sel.dataset.paymentMethodCode || '') : '';
    var amount = parseFloat(form.dataset.amount || '0') || 0;
    return code === 'paypal_bnpl' && amount < 30;
  }
  var MSG = 'PayPal Paga in 3 richiede almeno 30,00 € di ordine.';
  // Sotto i 30 € la riga non si mostra proprio (come fa Nexi in cassa).
  function hideBnplRow() {
    var amount = parseFloat(form.dataset.amount || '0') || 0;
    if (amount >= 30) { return; }
    var mark = form.querySelector('.nexi-apm-row[data-method-code="paypal_bnpl"]');
    var li = mark && mark.closest ? mark.closest('li[name=o_payment_option]') : null;
    if (li) { li.style.setProperty('display', 'none', 'important'); }
  }
  hideBnplRow();
  // Il "Pay now" sta fuori dal form e Odoo chiama form.submit():
  // l'evento submit non passa, quindi guardo il click a livello pagina.
  document.addEventListener('click', function (ev) {
    var btn = ev.target && ev.target.closest ? ev.target.closest('button[type="submit"]') : null;
    if (!btn || !tooSmall()) { return; }
    ev.preventDefault();
    ev.stopImmediatePropagation();
    show(MSG);
  }, true);
  form.addEventListener('submit', function (ev) {
    if (!tooSmall()) { return; }
    ev.preventDefault();
    ev.stopPropagation();
    show(MSG);
  }, true);
})();

div.script:
(function () {
  // Il form di Odoo non porta campi suoi fino al provider: la scelta
  // la salvo in sessione e il server la rilegge quando crea l'ordine.
  var pending = 0;
  function send(contract) {
    pending += 1;
    return fetch('/payment/nexi/saved-card', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({jsonrpc: '2.0', id: 1, params: {contract_id: contract || ''}}),
    }).catch(function () {}).then(function () { pending -= 1; });
  }
  // Non lascio partire il pagamento mentre la scelta sta ancora
  // viaggiando: altrimenti la transazione legge quella precedente.
  function whenSaved(cb) {
    if (!pending) { cb(); return; }
    var t0 = Date.now();
    (function loop() {
      if (!pending || Date.now() - t0 > 3000) { cb(); return; }
      setTimeout(loop, 40);
    })();
  }
  document.addEventListener('submit', function (ev) {
    if (!pending) { return; }
    ev.preventDefault();
    ev.stopImmediatePropagation();
    var form = ev.target;
    whenSaved(function () {
      if (form.requestSubmit) { form.requestSubmit(); } else { form.submit(); }
    });
  }, true);
  document.addEventListener('click', function (ev) {
    var b = ev.target && ev.target.closest
      ? ev.target.closest('button[type="submit"], button[name="o_payment_submit_button"]')
      : null;
    if (!b || !pending) { return; }
    ev.preventDefault();
    ev.stopImmediatePropagation();
    whenSaved(function () { b.click(); });
  }, true);
  document.addEventListener('change', function (ev) {
    if (!ev.target.classList || !ev.target.classList.contains('nexi-saved-radio')) return;
    // Selezionare una carta sceglie anche la riga Carta.
    var row = ev.target.closest('li[name=o_payment_option]');
    var r = row ? row.querySelector('input[data-payment-method-code="card"]') : null;
    if (r && !r.checked) r.click();
    send(ev.target.value);
  });
  // La scelta mostrata è quella che vale, anche se non la tocchi:
  // "Usa una nuova carta" non deve riusare la carta vecchia.
  function sendCurrent() {
    var sel = document.querySelector('.nexi-saved-radio:checked');
    send(sel ? sel.value : '');
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', sendCurrent);
  } else {
    sendCurrent();
  }
})();

t.script:
(function () {
  var done = false;
  // I loghi dei metodi nascono lazy dentro un contenitore stretto e
  // restano 0x0: forzo il caricamento e tolgo l'altezza 1px.
  document.querySelectorAll('li[name=o_payment_option] img').forEach(function (im) {
    im.setAttribute('loading', 'eager');
    im.removeAttribute('style');
    if (im.complete && im.naturalWidth === 0) {
      var src = im.getAttribute('src');
      im.setAttribute('src', src);
    }
  });
  window.addEventListener('error', function (e) {
    try {
      fetch('/payment/nexi/build/jserror', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({msg: 'ERR:' + String((e && e.message) || e).slice(0, 300)}),
      }).catch(function () {});
    } catch (ee) {}
  });
  window.addEventListener('unhandledrejection', function (e) {
    try {
      fetch('/payment/nexi/build/jserror', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({msg: 'REJ:' + String((e && e.reason) || e).slice(0, 300)}),
      }).catch(function () {});
    } catch (ee) {}
  });
  function submitBtn() { return document.querySelector('button[name="o_payment_submit_button"]'); }
  function showSubmit(show) {
    var b = submitBtn();
    if (b) b.classList.toggle('d-none', !show);
  }
  // La riga che contiene il nostro pannello (o il marcatore APM).
  function nexiRow() {
    var b = document.getElementById('nexi-inline');
    return b ? b.closest('li[name=o_payment_option]') : null;
  }
  function nexiRowSelected() {
    var sel = document.querySelector('input[name="o_payment_radio"]:checked');
    if (!sel) return false;
    var row = sel.closest('li[name=o_payment_option]');
    return !!(row && (row.querySelector('#nexi-inline') || row.querySelector('.nexi-apm-row')));
  }
  // Il "Pay now" fuori dal form serve a tutti: lo nascondo solo
  // quando il cliente ha scelto una riga Nexi (dove si paga dal
  // pannello). Con un altro provider deve restare visibile.
  function syncSubmit() { showSubmit(!nexiRowSelected()); }
  document.addEventListener('change', function (ev) {
    if (ev.target && ev.target.name === 'o_payment_radio') syncSubmit();
  }, true);
  document.addEventListener('click', function (ev) {
    if (ev.target && ev.target.closest && ev.target.closest('div[for="o_payment_radio"]')) syncSubmit();
  }, true);
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', syncSubmit);
  } else {
    syncSubmit();
  }
  function toast(msg) {
    var t = document.getElementById('nexi-toast');
    if (!t) {
      t = document.createElement('div');
      t.id = 'nexi-toast';
      t.style.cssText = 'position:fixed;left:50%;bottom:24px;transform:translateX(-50%);' +
        'background:#8b1b1b;color:#fff;padding:10px 16px;border-radius:8px;z-index:9999;' +
        'font-size:14px;box-shadow:0 4px 14px rgba(0,0,0,.25)';
      document.body.appendChild(t);
    }
    t.textContent = msg;
    t.style.display = 'block';
    clearTimeout(t._h);
    t._h = setTimeout(function () { t.style.display = 'none'; }, 6000);
  }
  function fail(msg) {
    var e = document.getElementById('nexi-inline-error');
    if (e) { e.textContent = msg; e.classList.remove('d-none'); }
  }
  // Nessuna navigazione verso URL che non siano Nexi: il valore può
  // arrivare dall'SDK o da una risposta alterata.
  function nexiUrlOk(u) {
    try {
      var x = new URL(u, window.location.href);
      if (x.protocol !== 'https:') { return false; }
      var h = x.hostname.toLowerCase();
      return h === 'xpay.nexigroup.com' || h === 'xpaysandbox.nexigroup.com';
    } catch (e) { return false; }
  }
  function iframeFor(f, height) {
    var i = document.createElement('iframe');
    i.src = f.src; i.scrolling = 'no';
// Titolo e nome: aiutano lettori di schermo e compilatori
// automatici a capire cos'e' il campo dentro l'iframe.
var _titles = {CARD_NUMBER: 'Numero carta', EXPIRATION_DATE: 'Scadenza', SECURITY_CODE: 'Codice di sicurezza', CARDHOLDER_NAME: 'Nome e cognome', CARDHOLDER_SURNAME: 'Cognome', CARDHOLDER_EMAIL: 'Email'};
i.setAttribute('title', 'Nexi - ' + (_titles[f.id] || f.id || 'campo carta'));
i.setAttribute('name', 'nexi-' + String(f.id || 'campo').toLowerCase().replace(/_/g, '-'));
    i.style.border = '0'; i.style.width = '100%';
    i.style.height = height || '60px';
    return i;
  }
  function loadSdk(src, cb) {
    if (window.Build) return cb();
    var s = document.createElement('script');
    if (!nexiUrlOk(src)) { return; }
    s.src = src; s.onload = cb;
    s.onerror = function () { fail('SDK Nexi non caricato. Riprova.'); };
    document.head.appendChild(s);
  }
  // La sessione Nexi invecchia: dopo 10 minuti i campi muoiono
  // (errori strani anche con dati giusti). Meglio rifarli.
  function sessionStale() {
    var box = document.getElementById('nexi-inline');
    var t = box && parseInt(box.dataset.preparedAt || '0', 10);
    return !t || (Date.now() - t > 10 * 60 * 1000);
  }
  function refreshSession() {
    done = false;
    prepare(true);
  }
  function prepare(show) {
    var box = document.getElementById('nexi-inline');
    if (!box || done) { return; }
    done = true;
    if (show) box.classList.remove('d-none');
    // Solo la casella "salva carta" della NOSTRA riga: quella degli
    // altri provider non va toccata.
    var myRow = nexiRow();
    var tok = myRow ? myRow.querySelector('input[name="o_payment_tokenize_checkbox"]') : null;
    var tokBox = tok ? tok.closest('div[name="o_payment_tokenize_container"], div.o-checkbox') : null;
    if (tokBox) tokBox.style.display = 'none';
    fetch('/payment/nexi/build/prepare', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({jsonrpc: '2.0', id: 1, params: {}}),
    }).then(function (r) { return r.json(); }
    ).then(function (res) {
      var r = (res && res.result) || res || {};
      if (r.error) { done = false; fail(r.error || 'Form non caricato. Riprova.'); return; }
      box.dataset.preparedAt = String(Date.now());
      box.dataset.finalize = r.finalize_url;
      box.dataset.confirm = r.confirm_url;
      var fb = document.getElementById('nexi-inline-fields');
      fb.innerHTML = '';
      var LABELS = {
        CARD_NUMBER: 'Numero carta',
        EXPIRATION_DATE: 'Scadenza',
        SECURITY_CODE: 'Codice di sicurezza',
        CARDHOLDER_NAME: 'Nome e cognome',
        CARDHOLDER_SURNAME: 'Cognome',
        CARDHOLDER_EMAIL: 'Email',
      };
      (r.fields || []).forEach(function (f) {
        if (!f || !f.src) return;
        var wrap = document.createElement('div');
        wrap.className = 'nexi-field';
        wrap.setAttribute('data-nexi-field', f.id || '');
        var lab = LABELS[f.id];
        if (lab) {
          var l = document.createElement('label');
          l.className = 'small text-600 mb-0';
          l.textContent = lab;
          wrap.appendChild(l);
        }
        wrap.appendChild(iframeFor(f, '46px'));
        fb.appendChild(wrap);
      });
      if (fb.children.length) {
        document.getElementById('nexi-inline-privacy-wrap').classList.remove('d-none');
        document.getElementById('nexi-inline-pay').style.display = '';
      } else {
        done = false; fail('Nessun campo carta disponibile.'); return;
      }
      hideUnavailable(r.buttons);
      loadSdk(r.sdk, initBuild);
    }).catch(function () { done = false; fail('Form non caricato. Riprova.'); });
  }
  var BTNMAP = {googlepay: 'GOOGLEPAY', applepay: 'APPLEPAY', bancomatpay: 'BANCOMATPAY', mybank: 'MYBANK', paypal: 'PAYPAL'};
  // Nascondo le righe il cui metodo Nexi non offre davvero.
  function hideUnavailable(buttons) {
    var ids = {};
    (buttons || []).forEach(function (f) { if (f && f.id) ids[f.id] = 1; });
    document.querySelectorAll('.nexi-apm-row').forEach(function (mark) {
      var svc = BTNMAP[mark.dataset.methodCode] || '';
      var li = mark.closest('li[name=o_payment_option]');
      if (!li) return;
      if (svc && !ids[svc]) li.style.setProperty('display', 'none', 'important');
    });
  }
  function initBuild() {
    try {
      window.__nexiBuild = new Build({
        onBuildFlowStateChange: function (evtData, workflowState) {
          var d = evtData || {};
          var state = d.state || workflowState || '';
          var box = document.getElementById('nexi-inline');
          if (d.url) { if (!nexiUrlOk(d.url)) { fail('Risposta Nexi non valida.'); return; } window.location.href = d.url; return; }
          if (state === 'READY_FOR_PAYMENT') { finalize(box); }
          if (state === 'PAYMENT_COMPLETE') { window.location.href = box.dataset.confirm; }
        },
        onBuildError: function (d) {
          var txt = '';
          try { txt = JSON.stringify(d || {}).slice(0, 300); } catch (e) { txt = String(d); }
          try {
            fetch('/payment/nexi/build/jserror', {
              method: 'POST',
              headers: {'Content-Type': 'application/json'},
              body: JSON.stringify({jsonrpc: '2.0', id: 1, params: {msg: 'onBuildError ' + txt}}),
            });
          } catch (e2) {}
          var info = d || {};
          if (info.id) {
            // Errore di un singolo campo mentre si scrive: lo mostro
            // sotto quel campo, senza bloccare tutto il pagamento.
            fieldError(info.id, info.errorMessage || 'Controlla questo campo.');
            return;
          }
          fail('Errore Nexi. Riprova.');
        },
        onConfirmError: function () {
          if (sessionStale()) {
            refreshSession();
            fail('Sessione scaduta: campi rinnovati, ricompila e premi Pay now.');
            return;
          }
          fail('Dati non validi. Controlla e riprova.');
        },
      });
    } catch (e) { fail('SDK Nexi non caricato. Riprova.'); return; }
    var payBtn = document.getElementById('nexi-inline-pay');
    if (payBtn && !payBtn.dataset.hook) {
      payBtn.dataset.hook = '1';
      payBtn.addEventListener('click', function (ev) {
        ev.preventDefault();
        if (!document.getElementById('nexi-inline-privacy').checked) {
          fail('Spunta la privacy per continuare.'); return;
        }
        if (sessionStale()) {
          refreshSession();
          fail('Sessione scaduta: campi rinnovati, ricompila e premi Pay now.');
          return;
        }
        if (window.__nexiBuild) { window.__nexiBuild.confirmData(function () {}); }
      });
    }
    var oForm = document.getElementById('o_payment_form');
    if (oForm && !oForm.dataset.nexiHook) {
      oForm.dataset.nexiHook = '1';
      oForm.addEventListener('submit', function (ev) {
        var myRow = nexiRow();
        var cardRadio = myRow ? myRow.querySelector('input[data-payment-method-code="card"]') : null;
        var box = document.getElementById('nexi-inline');
        if (cardRadio && cardRadio.checked && box && !box.classList.contains('d-none') && box.dataset.finalize && window.__nexiBuild) {
          ev.preventDefault();
          ev.stopPropagation();
          if (!document.getElementById('nexi-inline-privacy').checked) {
            fail('Spunta la privacy per continuare.'); return;
          }
          if (sessionStale()) {
            refreshSession();
            fail('Sessione scaduta: campi rinnovati, ricompila e premi Pay now.');
            return;
          }
          window.__nexiBuild.confirmData(function () {});
        }
      }, true);
    }
  }
  function fieldError(fieldId, msg) {
    var wrap = document.querySelector('[data-nexi-field="' + fieldId + '"]');
    if (!wrap) return;
    var hint = wrap.querySelector('.nexi-field-error');
    if (!hint) {
      hint = document.createElement('small');
      hint.className = 'nexi-field-error text-danger d-block mt-1';
      wrap.appendChild(hint);
    }
    hint.textContent = msg;
    var f = wrap.querySelector('iframe');
    if (f) { f.style.borderColor = '#c02b2b'; }
    clearTimeout(hint._h);
    hint._h = setTimeout(function () { hint.textContent = ''; if (f) f.style.borderColor = ''; }, 8000);
  }
  function finalize(box) {
    fetch(box.dataset.finalize, {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: '{}',
    }).then(function (r) { return r.json(); }
    ).then(function (res) {
      var r = (res && res.result) || res || {};
      if (r.error) { fail('Nexi: ' + r.error); return; }
      if (r.url) { if (!nexiUrlOk(r.url)) { fail('Risposta Nexi non valida.'); return; } window.location.href = r.url; return; }
      window.location.href = box.dataset.confirm;
    }).catch(function () { fail('Conferma non riuscita. Riprova.'); });
  }
  document.addEventListener('click', function (ev) {
    var t = ev.target;
    // Odoo manda due click (label + input): ne gestiamo uno solo.
    if (!t || t.tagName === 'INPUT') return;
    // Solo il bottone Carta apre/chiude: il resto della riga e i campi no.
    var pill = t && t.closest ? t.closest('div[for="o_payment_radio"]') : null;
    if (!pill) return;
    var row = pill.closest('li[name=o_payment_option]');
    if (!row || !row.querySelector('#nexi-inline')) return;
    var b = document.getElementById('nexi-inline');
    if (b && !b.classList.contains('d-none')) { b.classList.add('d-none'); return; }
    if (b) {
      b.classList.remove('d-none');
      // Sessione vecchia = campi morti: li rifaccio subito,
      // prima che il cliente ci scriva dentro.
      if (!b.querySelector('iframe') || sessionStale()) { refreshSession(); }
    }
    var r = row.querySelector('input[data-payment-method-code="card"]');
    if (r) { try { r.checked = true; } catch (e) {} }
    prepare(true);
  });
  document.addEventListener('click', function (ev) {
    var t = ev.target;
    var row = t && t.closest ? t.closest('li[name=o_payment_option]') : null;
    if (!row) return;
    var apm = row.querySelector('.nexi-apm-row');
    if (!apm || apm.dataset.busy) return;
    apm.dataset.busy = '1';
    var code = apm.dataset.methodCode;
    if (!code) return;
    fetch('/payment/nexi/build/prepare', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({jsonrpc: '2.0', id: 1, params: {method_code: code}}),
    }).then(function (r) { return r.json(); }
    ).then(function (res) {
      var r = (res && res.result) || res || {};
      if (r.url) { if (!nexiUrlOk(r.url)) { fail('Risposta Nexi non valida.'); return; } window.location.href = r.url; return; }
      delete apm.dataset.busy;
      if (r.hide) { row.style.setProperty('display', 'none', 'important'); }
      toast(r.error || 'Metodo non disponibile. Riprova.');
    }).catch(function () {
      delete apm.dataset.busy;
      toast('Metodo non disponibile. Riprova.');
    });
  });
  // Carico in background ma NON apro: la carta si apre solo se la scegli.
  prepare(false);
  setTimeout(function () {
    var fb = document.getElementById('nexi-inline-fields');
    if (fb && !fb.querySelector('iframe')) {
      fail('Campi non arrivati. Premi Pay now per continuare.');
      syncSubmit();
    }
  }, 12000);
})();
